        # If no explicit content in updates, attempt to extract from user_intent heuristics (only when clear 'send' intent)
        if not content:
            if isinstance(user_intent, str) and user_intent.strip().lower().startswith("send"):
                # weak heuristic: not sufficient to auto-fill content
