            kwargs["phone_number"] = normalize_phone(upd.get("phone_number"))
        if "recipient_person_id" in upd and upd.get("recipient_person_id"):
            kwargs["recipient_person_id"] = upd.get("recipient_person_id")
        if content:
            kwargs["content"] = content
        elif "content" in upd and upd.get("content"):
            kwargs["content"] = upd.get("content")

        # Validate we have recipient and content
